const chapters=[
 {title:'Тихий архив',place:'РАЙОН СОЛЁНЫХ ДОКОВ · 17-Й КВАРТАЛ',district:'СОЛЁНЫЕ ДОКИ — СТАРЫЙ АРХИВ',label:'Глава 01 / проникновение',objective:'Забрать реестр',detail:'Он докажет, кто продаёт городскую стражу.',target:[957,313],exit:[1138,397],exitTitle:'Скрыться с доков',exitDetail:'Доберитесь до шлюза на востоке.',intro:'За тринадцать лет до Чёрного дождя город затопил нижние кварталы и объявил погибшими тысячи жителей. Теперь кто-то тайно выкупает их имена из архива. Ирена Вейл знает цену одному из них: в старом реестре записана её сестра, пропавшая в ночь эвакуации.\n\nСвязной оставил шифр: «Если бумага пережила воду — значит, кто-то очень хотел, чтобы мы её нашли». В доках уже сменили патрули. Войди тихо, забери книгу и не верь первому имени на странице.',speaker:'ИРЕНА ВЕЙЛ · ПЕРЕД ВЫХОДОМ'},
 {title:'Колокол под водой',place:'ЗАТОПЛЕННЫЙ ПРИХОД · НИЖНИЕ ДОКИ',district:'НИЖНИЙ ПРИХОД — ЗАТОНУВШАЯ КАПЕЛЛА',label:'Глава 02 / поиск свидетеля',objective:'Найти журнал звонаря',detail:'Сверьте время эвакуации с записями прихода.',target:[310,354],exit:[78,335],exitTitle:'Добраться до насосной',exitDetail:'Монах укроет вас у старого насоса.',intro:'В реестре три тысячи имён, но только одно повторяется в списках погибших и в платёжных ведомостях: звонарь Эдрик. Сестра Агата узнаёт его почерк — он много лет передавал ей письма без обратного адреса.\n\nВ затопленной капелле сохранился журнал приливов. Если колокол звонил после приказа об эвакуации, значит, людей вывели не из города, а куда-то глубже. Найди записи. У часовни нет дверей, зато у воды длинная память.',speaker:'СЕСТРА АГАТА · ЗАПИСЬ ИЗ ДНЕВНИКА'},
 {title:'Пепельная биржа',place:'РЫНОК КОТЕЛЬЩИКОВ · ВЕРХНИЙ ЯРУС',district:'РЫНОК КОТЕЛЬЩИКОВ — ЧЁРНАЯ БИРЖА',label:'Глава 03 / обмен',objective:'Изъять книгу сделок',detail:'Имена покупателей ведут к городской канцелярии.',target:[957,313],exit:[1138,397],exitTitle:'Встретиться с курьером',exitDetail:'Перейдите по мосту к северной стене.',intro:'Журнал звонаря пережил воду в масляном чехле. Последняя запись: «Третий гудок — и они открыли ворота под литейной». В ту ночь официальный сигнал прозвучал только дважды. Кто-то подделал третий, чтобы увести людей в закрытый сектор.\n\nСлед обрывается на Пепельной бирже, где продают всё, чему не нашлось места в городских отчётах: лекарства, пропуска и чужие личности. Оскар должен выкупить книгу сделок. Не называй цену вслух — стены здесь принадлежат тому, кто предложит больше.',speaker:'ОСКАР РУН · УСЛОВИЕ СДЕЛКИ'},
 {title:'Свидетель без лица',place:'КВАРТАЛ МАЯКОВ · СТАНЦИЯ СИГНАЛОВ',district:'КВАРТАЛ МАЯКОВ — СИГНАЛЬНАЯ СТАНЦИЯ',label:'Глава 04 / спасение',objective:'Открыть камеру свидетеля',detail:'Внутри держат диспетчера ночной эвакуации.',target:[602,453],exit:[1138,397],exitTitle:'Вывести свидетеля',exitDetail:'Доставьте диспетчера к старому шлюзу.',intro:'В книге сделок одно имя стёрто ножом, но Вера различает вдавленные буквы: Марен, начальник ночной диспетчерской. Он жив. Его держат на станции маяков, чтобы он не подтвердил, кто отдал ложный приказ.\n\nДанте когда-то носил форму городской стражи и знает пароль смены, но не знает, кого сегодня считает своим врагом. Освободи Марена. Если он заговорит, все услышат правду; если нет — у нас останется только бумага против пушек.',speaker:'ДАНТЕ КРЕЙ · СООБЩЕНИЕ ГРУППЕ'},
 {title:'Город на цепи',place:'ШЛЮЗОВОЙ ДОМ · ВОСТОЧНАЯ ДАМБА',district:'ВОСТОЧНАЯ ДАМБА — ДОМ ЗАСЛОНОК',label:'Глава 05 / саботаж',objective:'Отключить цепь затворов',detail:'Насосы держат нижние кварталы под водой.',target:[883,492],exit:[1090,346],exitTitle:'Уйти до подъёма воды',exitDetail:'Выход — через башню смотрителя.',intro:'Марен подтвердил страшное: нижний город не затопило случайно. Затворы заперли по приказу Совета, чтобы скрыть незаконную эвакуацию рабочих в шахты под дамбой. Их потом объявили погибшими и продали их дома.\n\nНокс считает, что цепь затворов можно остановить, не обрушив дамбу. Ему понадобится время, а вам — отвлечь стражу. Ниже нас живут потомки тех, кого вычеркнули. Не открывай шлюзы наугад: город уже однажды заплатил за чужое милосердие.',speaker:'ФЕЛИКС НОКС · ПЛАН НА ОБРЫВКЕ КАРТЫ'},
 {title:'Имена в пепле',place:'БАШНЯ СОВЕТА · СЕРДЦЕ ГАВАНИ',district:'БАШНЯ СОВЕТА — ЗАЛ ПРИЛИВОВ',label:'Глава 06 / последний выбор',objective:'Передать доказательства',detail:'Решите, кому достанется правда о затоплении.',target:[957,313],exit:[1138,397],exitTitle:'Выйти к рассвету',exitDetail:'Последний путь ведёт через восточный шлюз.',intro:'Насосы остановлены. Под дамбой загорелись окна — целый город, которого не было на картах. Совет предлагает сделку: уничтожить реестр и получить безопасный проход для всех. Марен требует обнародовать имена виновных. Агата напоминает: публикация может вызвать расправу над детьми тех, кто подписал приказ.\n\nВ башне хранится оригинал распоряжения и список жителей нижнего города. До рассвета нужно решить, кому отдать документы. Гавань пережила ложную память. Переживёт ли она правду?',speaker:'МИРА СОЛТ · ПОСЛЕДНЯЯ НОЧЬ'}
];
