function blink(){if(blinkCd>0||won||lost||storyOpen)return;let range=hero===2?190:155,ox=player.x,oy=player.y;for(let i=1;i<=24;i++){let x=ox+Math.cos(player.a)*range*i/24,y=oy+Math.sin(player.a)*range*i/24;if(isBlocked(x,y,12))break;player.x=x;player.y=y}if(Math.hypot(player.x-ox,player.y-oy)>35){blinkCd=hero===2?3.5:5;player.suspicion=Math.max(0,player.suspicion-12);showToast('Шип перенёс вас сквозь тень')}else showToast('Путь преграждён')}
