 let ix=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+(touch.right?1:0)-(touch.left?1:0)+joystick.x,iy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+(touch.down?1:0)-(touch.up?1:0)+joystick.y,moving=Math.abs(ix)+Math.abs(iy)>.05,sneak=keys.shift||keys.sneak||touch.sneak,len=Math.hypot(ix,iy)||1;ix/=len;iy/=len;if(moving){let speed=(sneak?88:158)*heroes[hero].speed,forward=-iy,right=ix,dx=Math.cos(player.a)*forward-Math.sin(player.a)*right,dy=Math.sin(player.a)*forward+Math.cos(player.a)*right,nx=player.x+dx*speed*dt,ny=player.y+dy*speed*dt;if(!isBlocked(nx,player.y))player.x=nx;if(!isBlocked(player.x,ny))player.y=ny;player.stepNoise+=dt*(sneak?.48:1.6);if(player.stepNoise>(sneak?1.1:.34)){player.stepNoise=0;if(!sneak)player.noisyStep=true}}
 let dark=inShadow(player.x,player.y);player.hidden=dark&&sneak;let maxHeat=0;
