 let d=dist(g,player),ang=Math.atan2(player.y-g.y,player.x-g.x),delta=Math.atan2(Math.sin(ang-g.a),Math.cos(ang-g.a)),visible=Math.abs(delta)<g.look&&d<g.range&&!blockedBetween(g.x,g.y,player.x,player.y),lightMod=dark?.42:1,movementMod=moving?(sneak?.42:1.1):.7;if(hero===3)lightMod*=.72;if(hero===5&&dark)lightMod*=.65;
