@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Playfair+Display:wght@500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#0c1110;--panel:#151c19;--line:#354039;--muted:#9caa9f;--cream:#eadfc4;--gold:#d8b76e;--red:#d46b58;--teal:#7aa99a}
*{box-sizing:border-box}
html,body{margin:0;min-height:100%;background:#0b100f;color:var(--cream);font-family:Manrope,Arial,sans-serif}
body{overflow-x:hidden;background:radial-gradient(ellipse at 48% -15%,#27312a 0,#111816 40%,#0b100f 78%)}
button{font:inherit;color:inherit;cursor:pointer}
button:focus-visible{outline:2px solid var(--gold);outline-offset:3px}
.app{width:min(1500px,100%);margin:auto;padding:20px 24px 24px}
.topbar{height:56px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #29332d;margin-bottom:16px}
.brand{display:flex;align-items:center;gap:12px}.sigil{width:33px;height:33px;border:1px solid #b89a5c;color:#d9bd7a;display:grid;place-items:center;transform:rotate(45deg);font-family:serif;font-size:19px}.sigil span{transform:rotate(-45deg)}
.brand-title{font:600 16px 'Playfair Display',serif;letter-spacing:.13em;text-transform:uppercase}.brand-sub{font:10px 'DM Mono',monospace;color:#8e9b90;letter-spacing:.16em;margin-top:3px}.top-right{font:10px 'DM Mono',monospace;color:#819086;letter-spacing:.12em}.top-right b{color:#d8b76e;font-weight:400}
.layout{display:grid;grid-template-columns:252px minmax(0,1fr) 260px;gap:16px;align-items:stretch}.side{background:linear-gradient(145deg,rgba(26,35,30,.97),rgba(17,24,21,.98));border:1px solid #354039;position:relative;overflow:hidden}.side:before{content:"";position:absolute;inset:0 auto 0 0;width:2px;background:linear-gradient(transparent,#b59a60,transparent);opacity:.7}.left{padding:21px 18px;display:flex;flex-direction:column;gap:0}.eyebrow{font:10px 'DM Mono',monospace;color:#b9a16d;letter-spacing:.19em;text-transform:uppercase}.left h1{font:600 29px/1.05 'Playfair Display',serif;margin:10px 0 8px;letter-spacing:-.02em}.place{font:10px 'DM Mono',monospace;color:#829187;letter-spacing:.11em;line-height:1.55}.rule{height:1px;background:#354039;margin:17px 0;flex:none}
.objective{font-size:12px;color:#c4c9ba;line-height:1.55}.objective>.eyebrow{margin-bottom:13px}.obj-row{display:flex;gap:10px;margin:12px 0;align-items:flex-start}.obj-row>span:last-child{display:block}.obj-row strong{display:block;color:#e5d7b4;font-weight:600;margin-bottom:2px}.obj-row span span{display:block;color:#96a399;font-size:11px;line-height:1.45}.checkbox{width:15px;height:15px;border:1px solid #657064;flex:none;margin-top:2px;display:grid;place-items:center;color:#0f1713;font-size:11px}.checkbox.done{background:#a7ad78;border-color:#a7ad78}
.statusline{display:flex;justify-content:space-between;gap:6px;color:#95a197;font:9px 'DM Mono',monospace;letter-spacing:.06em;margin:12px 0 7px}.statusline span:last-child{color:#d6c597;text-align:right}.meter{height:4px;background:#29342e;overflow:hidden}.meter i{height:100%;display:block;width:100%;background:linear-gradient(90deg,#758b6d,#c4ad6d);transition:width .25s}.meter.heat i{background:linear-gradient(90deg,#718c70,#d6ac5d,#d66e55)}
.card-label{font:9px 'DM Mono',monospace;color:#839087;letter-spacing:.15em;margin-top:20px}.hero-mini{display:flex;align-items:center;gap:10px;margin-top:10px}.avatar{height:42px;width:42px;border-radius:50% 50% 4px 4px;background:var(--coat,#555);border:1px solid #8a7950;position:relative;overflow:hidden}.avatar:before{content:"";position:absolute;width:18px;height:20px;left:11px;top:7px;border-radius:50%;background:var(--skin,#bd9476);box-shadow:0 -7px 0 2px var(--hair,#222)}.avatar:after{content:"";position:absolute;left:3px;right:3px;height:17px;bottom:-4px;background:var(--coat,#555);border-radius:50% 50% 0 0}.hero-mini strong,.hero-mini span{display:block}.hero-mini strong{font:600 12px 'Playfair Display',serif}.hero-mini span{font:8px 'DM Mono',monospace;color:#9da99c;margin-top:4px}.bottom-note{color:#879489;font:italic 11px/1.55 'Playfair Display',serif;margin-top:auto;padding-top:22px}
.game-panel{min-width:0;background:#111815;border:1px solid #354039;box-shadow:0 12px 36px #0005;display:flex;flex-direction:column}.game-head{height:42px;padding:0 14px;display:flex;align-items:center;justify-content:space-between;gap:10px;border-bottom:1px solid #2d3831}.district{color:#d6c597;font:10px 'DM Mono',monospace;letter-spacing:.1em;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.weather{color:#78877d;font:9px 'DM Mono',monospace;letter-spacing:.1em;white-space:nowrap}.canvas-wrap{position:relative;width:100%;aspect-ratio:1200/790;min-height:300px;overflow:hidden;background:#1a231f;touch-action:none}.canvas-wrap canvas{display:block;width:100%;height:100%;object-fit:fill;cursor:crosshair;touch-action:none}.canvas-label{position:absolute;left:14px;top:13px;color:#c2c2a8;background:#111915a8;border:1px solid #c1b27655;padding:6px 8px;font:9px 'DM Mono',monospace;letter-spacing:.09em;pointer-events:none}.canvas-label span{color:#d8b76e;margin-left:5px}.crosshair{position:absolute;left:50%;top:50%;width:18px;height:18px;transform:translate(-50%,-50%);opacity:.55;pointer-events:none}.crosshair:before,.crosshair:after{content:"";position:absolute;background:#e6dfc6;box-shadow:0 0 4px #0b100f}.crosshair:before{width:1px;height:18px;left:8px;top:0}.crosshair:after{height:1px;width:18px;left:0;top:8px}.crosshair i{position:absolute;inset:6px;border:1px solid #e6dfc6;border-radius:50%}.crosshair b{display:none}.sound-wave{position:absolute;right:14px;top:151px;padding:5px 7px;background:#121915b8;color:#b9c3aa;font:8px 'DM Mono',monospace;letter-spacing:.1em;pointer-events:none}.toast{position:absolute;left:50%;top:48px;transform:translate(-50%,-8px);opacity:0;transition:.2s;max-width:85%;padding:8px 12px;background:#151c19ed;border:1px solid #a48d59;color:#eadfc4;font:10px 'DM Mono',monospace;text-align:center;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.interaction-prompt{position:absolute;left:50%;bottom:22%;transform:transl